<section class="single-herbs-guide__section" aria-labelledby="topic-seven-foundations"><h4 id="topic-seven-foundations"><?php echo s($defheattext('Herbs That Clear Deficient Heat: general introduction', 'Hierbas que aclaran Calor por deficiencia: introducción general')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($defheattext('This category addresses lingering or low-grade Heat when Yin and fluids have been injured. Board questions are solved by asking whether Heat must be vented, whether sweating is present and whether Lung, Blood or urination clues accompany the fever.', 'Esta categoría aborda Calor persistente o de baja intensidad cuando Yin y líquidos han sido lesionados. Las preguntas Board se resuelven preguntando si el Calor debe exteriorizarse, si existe sudoración y si acompañan pistas de Pulmón, Sangre u orina.')); ?></p><div class="single-herbs-guide__pattern"><article><strong><?php echo s($defheattext('Typical presentation', 'Presentación típica')); ?></strong><span><?php echo s($defheattext('Low-grade or night fever, five-center Heat, steaming bones, night sweating, dry mouth and a thin rapid pulse.', 'Fiebre baja o nocturna, Calor en cinco centros, huesos humeantes, sudor nocturno, boca seca y pulso fino rápido.')); ?></span></article><article><strong><?php echo s($defheattext('Choose by mechanism', 'Elige por mecanismo')); ?></strong><span><?php echo s($defheattext('Vent latent Heat, cool Lung/Blood and urinate, or clear Kidney/Lung deficiency Heat with sweating.', 'Exteriorizar Calor latente, enfriar Pulmón/Sangre y promover orina, o aclarar Calor por deficiencia de Riñón/Pulmón con sudoración.')); ?></span></article><article><strong><?php echo s($defheattext('Do not confuse', 'No confundas')); ?></strong><span><?php echo s($defheattext('Deficient Heat is not the same as intense Excess Fire, and clearing Heat is not identical to rebuilding Yin.', 'Calor por deficiencia no es lo mismo que Fuego intenso por exceso, y aclarar Calor no equivale a reconstruir Yin.')); ?></span></article></div><p class="single-herbs-guide__scope-note"><strong><?php echo s($defheattext('General precautions:', 'Precauciones generales:')); ?></strong> <?php echo s($defheattext('these cold herbs can weaken digestion. Confirm the deficient or residual-Heat mechanism instead of treating every chronic fever as Yin deficiency.', 'estas hierbas frías pueden debilitar la digestión. Confirma el mecanismo de deficiencia o Calor residual en vez de tratar toda fiebre crónica como deficiencia de Yin.')); ?></p><aside class="single-herbs-guide__memory-path" aria-label="<?php echo s($defheattext('Hidden embers memory house', 'Casa mnemotécnica de brasas ocultas')); ?>"><p class="single-herbs-guide__memory-line"><?php echo s($defheattext('After the toxicity alarm, the flames are gone—but three hidden embers keep the house warm at night.', 'Después de la alarma de toxicidad, las llamas desaparecieron, pero tres brasas ocultas mantienen la casa caliente de noche.')); ?></p><p><?php echo s($defheattext('Qing Hao opens the attic skylight to vent the hidden ember; Bai Wei cools the red hallway, clears the Lung room and opens the floor drain; Di Gu Pi cools the basement Kidney foundation and closes the sweating leak.', 'Qing Hao abre la claraboya para exteriorizar la brasa oculta; Bai Wei enfría el pasillo rojo, limpia el cuarto de Pulmón y abre el desagüe; Di Gu Pi enfría los cimientos de Riñón y cierra la fuga de sudor.')); ?></p><p><strong><?php echo s($defheattext('Hidden ember, different exit.', 'Brasa oculta, salida diferente.')); ?></strong></p></aside><h5 class="single-herbs-guide__catalog-heading"><?php echo s($defheattext('Current Board category herbs', 'Hierbas de la categoría Board vigente')); ?></h5><p class="single-herbs-guide__catalog-intro"><?php echo s($defheattext('The module names exactly these three herbs. Study them before opening the annex.', 'El módulo nombra exactamente estas tres hierbas. Estúdialas antes de abrir el anexo.')); ?></p><ol class="single-herbs-guide__category-herbs"><?php foreach ($defheatherbs as $categoryherb): ?><li class="single-herbs-guide__category-herb single-herbs-guide__category-herb--core"><div class="single-herbs-guide__category-herb-head"><strong><?php echo s($categoryherb['name']); ?></strong><em><?php echo s($categoryherb['latin']); ?></em><span class="single-herbs-guide__category-herb-badge"><?php echo s($defheattext('In Board category list', 'En el listado de la categoría Board')); ?></span></div><p><?php echo s($categoryherb['identity']); ?></p></li><?php endforeach; ?></ol><div class="single-herbs-guide__annex"><h5 class="single-herbs-guide__catalog-heading"><?php echo s($defheattext('Annex A · Additional official recognition herbs', 'Anexo A · Hierbas oficiales adicionales para reconocimiento')); ?></h5><ol class="single-herbs-guide__category-herbs"><?php foreach ($defheatofficialannex as $categoryherb): ?><li class="single-herbs-guide__category-herb"><div class="single-herbs-guide__category-herb-head"><strong><?php echo s($categoryherb['name']); ?></strong><em><?php echo s($categoryherb['latin']); ?></em><span class="single-herbs-guide__category-herb-badge"><?php echo s($defheattext('In current Appendix A', 'En el Appendix A vigente')); ?></span></div><p><?php echo s($categoryherb['note']); ?></p></li><?php endforeach; ?></ol><h5 class="single-herbs-guide__catalog-heading"><?php echo s($defheattext('Annex B · Yang recognition outside current list', 'Anexo B · Reconocimiento de Yang fuera del listado vigente')); ?></h5><ol class="single-herbs-guide__category-herbs"><?php foreach ($defheatoutsideannex as $categoryherb): ?><li class="single-herbs-guide__category-herb"><div class="single-herbs-guide__category-herb-head"><strong><?php echo s($categoryherb['name']); ?></strong><em><?php echo s($categoryherb['latin']); ?></em><span class="single-herbs-guide__category-herb-badge single-herbs-guide__category-herb-badge--outside"><?php echo s($defheattext('Outside current Appendix A', 'Fuera del Appendix A vigente')); ?></span></div><p><?php echo s($categoryherb['note']); ?></p></li><?php endforeach; ?></ol></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-seven-yang-title"><h4 id="topic-seven-yang-title"><?php echo s($defheattext('Yang comparative fingerprint', 'Huella comparativa de Yang')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($defheattext('These selected Chapter 3 bars connect mechanism to organ location. Values are relative study indices, not clinical percentages.', 'Estas barras seleccionadas del capítulo 3 conectan mecanismo con localización orgánica. Los valores son índices relativos de estudio, no porcentajes clínicos.')); ?></p><div class="single-herbs-guide__yang-charts"><?php foreach ($defheatcharts as $chart): ?><article class="single-herbs-guide__yang-chart"><h5><?php echo s($chart['title']); ?></h5><small><?php echo s($chart['figure']); ?></small><?php foreach ($chart['items'] as $herbname => $value): ?><div class="single-herbs-guide__yang-bar"><span><?php echo s($herbname); ?></span><span class="single-herbs-guide__yang-bar-track"><span class="single-herbs-guide__yang-bar-fill" style="width:<?php echo (int) $value; ?>%"></span></span><b><?php echo (int) $value; ?></b></div><?php endforeach; ?></article><?php endforeach; ?></div><p class="single-herbs-guide__yang-note"><strong><?php echo s($defheattext('Reading rule:', 'Regla de lectura:')); ?></strong> <?php echo s($defheattext('Qing Hao is the vent; Bai Wei joins Blood, Lung and urine; Di Gu Pi carries the clearest Kidney/Lung deficiency-Heat signal.', 'Qing Hao es la salida; Bai Wei une Sangre, Pulmón y orina; Di Gu Pi ofrece la señal más clara de Calor por deficiencia en Riñón/Pulmón.')); ?></p></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-seven-decision-title"><h4 id="topic-seven-decision-title"><?php echo s($defheattext('Fast decision map', 'Mapa de decisión rápida')); ?></h4><div class="single-herbs-guide__decision"><?php foreach ($defheatdecisions as $decision): ?><div><strong><?php echo s($decision[0]); ?></strong><span><?php echo s($decision[1]); ?></span></div><?php endforeach; ?></div></section>

