<section class="single-herbs-guide__section" aria-labelledby="topic-seven-formulas-title"><h4 id="topic-seven-formulas-title"><?php echo s($defheattext('When the herb leads the formula', 'Cuando la hierba dirige la fórmula')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($defheattext('Only chief or co-chief connections within the current 63-formula Board roster appear here.', 'Aquí aparecen solamente relaciones principales o coprincipales dentro del listado Board vigente de 63 fórmulas.')); ?></p><div class="single-herbs-guide__formula-leads"><article class="single-herbs-guide__formula-lead"><h5>Qing Hao + Bie Jia</h5><p><strong>Qing Hao Bie Jia Tang:</strong> <?php echo s($defheattext('Qing Hao vents latent Heat outward while Bie Jia enters the Yin level and nourishes the depleted root.', 'Qing Hao exterioriza Calor latente mientras Bie Jia entra al nivel Yin y nutre la raíz agotada.')); ?></p></article></div><p class="single-herbs-guide__scope-note"><strong><?php echo s($defheattext('Roster boundary:', 'Límite del listado:')); ?></strong> <?php echo s($defheattext('No additional formula is shown because no other chief or co-chief connection for these three herbs belongs to the current 63-formula Domain list.', 'No se muestra otra fórmula porque ninguna relación principal o coprincipal adicional para estas tres hierbas pertenece al listado vigente de 63 fórmulas del Domain.')); ?></p></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-seven-comparisons-title"><h4 id="topic-seven-comparisons-title"><?php echo s($defheattext('High-yield comparisons', 'Comparaciones de alto rendimiento')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($defheattext('Choose the mechanism mentally before opening the complete comparison.', 'Elige mentalmente el mecanismo antes de abrir la comparación completa.')); ?></p><div class="single-herbs-guide__comparisons"><?php foreach ($defheatcomparisons as $comparison): ?><?php $comparisonpath = $ises && !empty($comparison['path_es']) ? $comparison['path_es'] : $comparison['path']; $comparisonurl = new moodle_url($comparisonpath, ['from' => 'single-herbs', 'focus' => (string) $selected['number']]); ?><a class="single-herbs-guide__comparison" href="<?php echo $comparisonurl->out(false); ?>"><strong><?php echo s($comparison['title']); ?></strong><span><?php echo s($comparison['summary']); ?></span><small><?php echo s($defheattext('Open full comparison →', 'Abrir comparación completa →')); ?></small></a><?php endforeach; ?></div></section>

