<section class="single-herbs-guide__section" aria-labelledby="topic-seven-recall-title"><h4 id="topic-seven-recall-title"><?php echo s($defheattext('Quick recall', 'Repaso rápido')); ?></h4><div class="single-herbs-guide__recall"><details><summary><?php echo s($defheattext('Steaming bones without sweating?', '¿Huesos humeantes sin sudor?')); ?></summary><p><strong>Qing Hao.</strong> <?php echo s($defheattext('Think latent Heat needing an aromatic exit.', 'Piensa en Calor latente que necesita una salida aromática.')); ?></p></details><details><summary><?php echo s($defheattext('Steaming bones with sweating and Lung Heat?', '¿Huesos humeantes con sudor y Calor de Pulmón?')); ?></summary><p><strong>Di Gu Pi.</strong> <?php echo s($defheattext('Its Lung-Kidney emphasis is decisive.', 'Su énfasis Pulmón-Riñón es decisivo.')); ?></p></details><details><summary><?php echo s($defheattext('Residual fever plus difficult urination?', '¿Fiebre residual más dificultad urinaria?')); ?></summary><p><strong>Bai Wei.</strong> <?php echo s($defheattext('It cools Blood and Lung while opening the urinary route.', 'Enfría Sangre y Pulmón mientras abre la vía urinaria.')); ?></p></details><details><summary><?php echo s($defheattext('Which current formula pairs venting with Yin nourishment?', '¿Qué fórmula vigente combina exteriorización con nutrición de Yin?')); ?></summary><p><strong>Qing Hao Bie Jia Tang.</strong> Qing Hao + Bie Jia.</p></details></div></section>

